// Clean-room exact Delaunay graph construction by empty circumcircles.
#include <cstddef>
#include <cstdint>
namespace {constexpr std::size_t N=8,F=37;std::int64_t orient(std::int64_t ax,std::int64_t ay,std::int64_t bx,std::int64_t by,std::int64_t cx,std::int64_t cy){return (bx-ax)*(cy-ay)-(by-ay)*(cx-ax);}std::int64_t incircle(std::int64_t ax,std::int64_t ay,std::int64_t bx,std::int64_t by,std::int64_t cx,std::int64_t cy,std::int64_t dx,std::int64_t dy){ax-=dx;ay-=dy;bx-=dx;by-=dy;cx-=dx;cy-=dy;auto aa=ax*ax+ay*ay,bb=bx*bx+by*by,cc=cx*cx+cy*cy;return aa*(bx*cy-by*cx)-bb*(ax*cy-ay*cx)+cc*(ax*by-ay*bx);}void put(std::uint8_t*o,std::size_t at,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(int i=0;i<8;++i){o[at+i]=static_cast<std::uint8_t>(b);b>>=8;}}}
extern "C" std::int64_t voronoi_delaunay_empty_circle(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<7||n>17||v[0]<3||v[0]>8||n!=1+2*static_cast<std::size_t>(v[0]))return -1;auto count=static_cast<std::size_t>(v[0]);std::int64_t x[N],y[N];for(std::size_t i=0;i<count;++i){x[i]=v[1+2*i];y[i]=v[2+2*i];if(x[i]<-50||x[i]>50||y[i]<-50||y[i]>50)return -1;for(std::size_t j=0;j<i;++j)if(x[i]==x[j]&&y[i]==y[j])return -1;}
 for(std::size_t a=0;a<count;++a)for(std::size_t b=a+1;b<count;++b)for(std::size_t c=b+1;c<count;++c)if(orient(x[a],y[a],x[b],y[b],x[c],y[c])==0)return -1;for(std::size_t a=0;a<count;++a)for(std::size_t b=a+1;b<count;++b)for(std::size_t c=b+1;c<count;++c)for(std::size_t d=c+1;d<count;++d)if(incircle(x[a],y[a],x[b],y[b],x[c],y[c],x[d],y[d])==0)return -1;
 bool edge[N][N]{};for(std::size_t a=0;a<count;++a)for(std::size_t b=a+1;b<count;++b)for(std::size_t c=b+1;c<count;++c){auto o=orient(x[a],y[a],x[b],y[b],x[c],y[c]);bool empty=true;for(std::size_t d=0;d<count;++d)if(d!=a&&d!=b&&d!=c){auto z=incircle(x[a],y[a],x[b],y[b],x[c],y[c],x[d],y[d]);if((o>0&&z>0)||(o<0&&z<0)){empty=false;break;}}if(empty)edge[a][b]=edge[b][a]=edge[a][c]=edge[c][a]=edge[b][c]=edge[c][b]=true;}
 std::int64_t fields[F]{};std::size_t at=1,m=0;for(std::size_t a=0;a<count;++a)for(std::size_t b=a+1;b<count;++b)if(edge[a][b]){fields[at++]=a;fields[at++]=b;++m;}fields[0]=m;auto bytes=8*at;if(!out||cap<bytes)return -2;for(std::size_t i=0;i<at;++i)put(out,8*i,fields[i]);return static_cast<std::int64_t>(bytes);}
